dtsPropsFor.Badge:
/** Tom semântico do badge. @default 'muted' */
  variant?: 'positive' | 'negative' | 'accent' | 'warning' | 'muted';
  /** @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  /** Cor CSS de um ponto indicador à esquerda do texto (ex: cor da categoria). */
  dot?: string;
  children: React.ReactNode;
  className?: string;

dtsPropsFor.BalanceCard:
/** Rótulo acima do valor (ex: 'Saldo do mês'). */
  label: string;
  /** Valor já formatado como texto (ex: 'R$ 4.280,00'). */
  amount: string;
  /** Total de entradas, já formatado. Renderiza o rodapé quando presente. */
  income?: string;
  /** Total de saídas, já formatado. Renderiza o rodapé quando presente. */
  expense?: string;
  className?: string;

dtsPropsFor.BudgetBar:
/** Valor gasto até agora. */
  current: number;
  /** Orçamento alvo. */
  target: number;
  label?: React.ReactNode;
  /** Cor da barra. Quando omitido, deriva de current/target (>=80% warn, >100% over). */
  tone?: 'ok' | 'warn' | 'over' | 'accent';
  /** Texto extra à direita, depois dos valores. */
  hint?: React.ReactNode;
  /** @default formatCurrency (pt-BR / BRL) */
  formatValue?: (v: number) => string;
  className?: string;

dtsPropsFor.Button:
/** @default 'primary' */
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger' | 'positive' | 'surface';
  /** @default 'md' */
  size?: 'lg' | 'md' | 'sm' | 'xs' | 'icon';
  /** Renderiza o filho como o elemento (Radix Slot) em vez de <button>. */
  asChild?: boolean;
  /** Troca o conteúdo por um spinner e desabilita o botão. */
  loading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  children?: React.ReactNode;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  className?: string;
  [key: string]: unknown;

dtsPropsFor.Card:
/** Padding interno. @default 'none' */
  padding?: 'none' | 'sm' | 'md' | 'lg';
  children?: React.ReactNode;
  className?: string;
  [key: string]: unknown;

dtsPropsFor.Chip:
/** Estado selecionado — pinta borda e fundo com o accent. @default false */
  active?: boolean;
  leftIcon?: React.ReactNode;
  children?: React.ReactNode;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  className?: string;
  [key: string]: unknown;

dtsPropsFor.Combobox:
/** Opções agrupadas. Use `groups` OU `options`, não os dois. */
  groups?: { id: string; label: string; options: { value: string; label: string }[] }[];
  /** Opções sem agrupamento. */
  options?: { value: string; label: string }[];
  /** Value da opção selecionada (string vazia = nenhuma). */
  value: string;
  onValueChange: (value: string) => void;
  /** @default 'Buscar...' */
  placeholder?: string;
  error?: boolean;
  className?: string;

dtsPropsFor.CurrencyInput:
/** Nome do campo no FormData — o valor é submetido via input hidden em reais ('123.45'). */
  name: string;
  defaultValue?: string | number;
  required?: boolean;
  autoFocus?: boolean;
  /** @default 'R$ 0,00' */
  placeholder?: string;
  error?: boolean;
  /** Recebe o valor em centavos inteiros. Converta com (cents / 100).toFixed(2). */
  onValueChange?: (cents: number) => void;
  /** Mantém '0,00' visível quando zero é um valor legítimo (orçamentos, aportes). @default false */
  preserveExplicitZero?: boolean;
  className?: string;

dtsPropsFor.DeleteButton:
/** Executada ao confirmar. Lançar aqui exibe um toast de erro e fecha o diálogo. */
  onDelete: () => Promise<void>;
  /** @default 'Excluir item' */
  title?: string;
  /** @default 'Essa ação não pode ser desfeita.' */
  description?: string;
  /** Mensagem do toast quando onDelete rejeita. */
  errorMessage?: string;

dtsPropsFor.Dialog:
/** Radix Dialog.Root. Componha com DialogContent / DialogHeader / DialogTitle / DialogDescription / DialogFooter. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  defaultOpen?: boolean;
  modal?: boolean;
  children?: React.ReactNode;

dtsPropsFor.Drawer:
/** Drawer (vaul) para mobile. Componha com DrawerContent / DrawerHeader / DrawerTitle. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** @default true */
  shouldScaleBackground?: boolean;
  children?: React.ReactNode;

dtsPropsFor.EmptyState:
/** Ícone (lucide-react) — recebe caixa de 56px e é dimensionado para 28px. */
  icon?: React.ReactNode;
  title: string;
  description?: string;
  /** Passe um <Button> pronto, nunca um objeto { label, onClick }. */
  action?: React.ReactNode;
  /** Envolve em card com borda e sombra. @default false */
  boxed?: boolean;
  className?: string;

dtsPropsFor.Field:
/** Rótulo do campo (renderiza um <Label> do DS). */
  label?: string;
  /** Texto auxiliar — suprimido quando `error` está presente. */
  hint?: string;
  /** Mensagem de erro; substitui o hint. */
  error?: string;
  /** Acrescenta um asterisco vermelho ao label. */
  required?: boolean;
  children: React.ReactNode;
  className?: string;

dtsPropsFor.Input:
/** Pinta borda e anel de foco com o token negative. @default false */
  error?: boolean;
  type?: string;
  name?: string;
  value?: string | number;
  defaultValue?: string | number;
  placeholder?: string;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;
  [key: string]: unknown;

dtsPropsFor.Label:
htmlFor?: string;
  children?: React.ReactNode;
  className?: string;
  [key: string]: unknown;

dtsPropsFor.MonthSelect:
/** Nome no FormData — submete 'YYYY-MM' via input hidden. */
  name: string;
  /** 'YYYY-MM'. @default mês corrente */
  defaultValue?: string;
  error?: boolean;
  /** Meses para trás na lista. @default 12 */
  back?: number;
  /** Meses para frente na lista. @default 12 */
  forward?: number;

dtsPropsFor.MultiselectDropdown:
/** Texto do gatilho (pill). */
  label: string;
  /** `group` agrupa itens com separador e cabeçalho. */
  options: { value: string; label: string; group?: string }[];
  /** Values marcados. */
  selected: string[];
  onChange: (next: string[]) => void;
  className?: string;

dtsPropsFor.NumericInput:
/** Nome do campo no FormData — submete o número via input hidden ('12.50'). */
  name: string;
  defaultValue?: string | number;
  required?: boolean;
  autoFocus?: boolean;
  error?: boolean;
  /** Recebe o valor em centavos inteiros. */
  onValueChange?: (cents: number) => void;
  /** Mantém '0,00' visível quando zero é legítimo. @default false */
  preserveExplicitZero?: boolean;
  className?: string;

dtsPropsFor.Progress:
/** @default 0 */
  value?: number;
  /** @default 100 */
  max?: number;
  /** Classe da barra preenchida (ex: 'bg-positive'). */
  indicatorClassName?: string;
  /** Dimensiona o trilho (ex: 'h-1.5 w-20'). */
  className?: string;
  [key: string]: unknown;

dtsPropsFor.RowActions:
/** Omitir remove o item 'Editar' do menu. */
  onEdit?: () => void;
  /** Omitir remove o item 'Excluir'. Abre confirmação antes de executar. */
  onDelete?: () => Promise<void>;
  /** @default 'Excluir item' */
  deleteTitle?: string;
  /** @default 'Essa ação não pode ser desfeita.' */
  deleteDescription?: string;
  deleteErrorMessage?: string;
  /** Override do hover do gatilho em fundo colorido. */
  triggerClassName?: string;
  /** Renderizadas antes do separador Editar/Excluir. */
  additionalActions?: { label: string; icon?: React.ComponentType<{ className?: string }>; onClick: () => void; variant?: 'default' | 'destructive' }[];

dtsPropsFor.Section:
/** Renderizado como heading em caixa alta. */
  title: string;
  children: React.ReactNode;
  /** Nó alinhado à direita do título (normalmente um <Button size="xs">). */
  action?: React.ReactNode;
  className?: string;

dtsPropsFor.Segment:
/** Conjuntos pequenos e fixos (<= 4). Para N dinâmico use <Select>. */
  options: { value: string; label: React.ReactNode; activeClassName?: string }[];
  /** Controlado. Se omitido, o componente mantém estado interno. */
  value?: string;
  onChange?: (v: string) => void;
  className?: string;

dtsPropsFor.Select:
/** Radix Select.Root. Componha com SelectTrigger / SelectValue / SelectContent / SelectItem. Não popula FormData — espelhe o value num input hidden. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  disabled?: boolean;
  name?: string;
  children?: React.ReactNode;

dtsPropsFor.Separator:
/** @default 'horizontal' */
  orientation?: 'horizontal' | 'vertical';
  /** @default true */
  decorative?: boolean;
  className?: string;

dtsPropsFor.SummaryCard:
/** Cor da barra superior e do valor. */
  variant: 'balance' | 'positive' | 'negative';
  label: string;
  /** Valor já formatado como texto. */
  amount: string;
  footer?: string;
  icon?: React.ReactNode;
  className?: string;

dtsPropsFor.Switch:
label?: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
  disabled?: boolean;
  id?: string;

dtsPropsFor.Textarea:
error?: boolean;
  /** @default 4 */
  rows?: number;
  name?: string;
  value?: string;
  defaultValue?: string;
  placeholder?: string;
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
  className?: string;
  [key: string]: unknown;

dtsPropsFor.TxList:
/** Container da lista. Preencha com TxGroupHeader, TxItem, FixedExpenseItem e ListFooter (todos exportados pelo DS). */
  children: React.ReactNode;
  className?: string;
  [key: string]: unknown;
